import os, shutil, tempfile, zipfile
from pathlib import Path
t = Path(tempfile.mkdtemp())
(t/'src').mkdir()
(t/'out').mkdir()
for n in ('one.pdf', 'two.PDF', 'three.txt'):
    (t/'src'/n).write_text('x')
for folder, subs, files in os.walk(t/'src'):
    for name in files:
        if name.lower().endswith('.pdf'):
            shutil.copy(Path(folder)/name, t/'out')
print(sorted(p.name for p in (t/'out').iterdir()))
